import React from 'react';
import { motion } from 'framer-motion';
import './Skills.css';

// Original colored logos using Devicon
const skillsData = [
  { name: 'HTML5', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/html5/html5-original.svg', shadow: 'rgba(227, 79, 38, 0.4)' },
  { name: 'CSS3', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/css3/css3-original.svg', shadow: 'rgba(21, 114, 182, 0.4)' },
  { name: 'JavaScript', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/javascript/javascript-original.svg', shadow: 'rgba(247, 223, 30, 0.4)' },
  { name: 'React', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg', shadow: 'rgba(97, 218, 251, 0.4)' },
  { name: 'Node.js', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nodejs/nodejs-original.svg', shadow: 'rgba(51, 153, 51, 0.4)' },
  { name: 'Express.js', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/express/express-original.svg', shadow: 'rgba(255, 255, 255, 0.4)' },
  { name: 'MongoDB', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/mongodb/mongodb-original.svg', shadow: 'rgba(71, 162, 72, 0.4)' },
  { name: 'MySQL', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/mysql/mysql-original.svg', shadow: 'rgba(68, 121, 161, 0.4)' },
  { name: 'Python', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/python/python-original.svg', shadow: 'rgba(55, 118, 171, 0.4)' },
  { name: 'C', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/c/c-original.svg', shadow: 'rgba(168, 185, 204, 0.4)' },
  { name: 'C++', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/cplusplus/cplusplus-original.svg', shadow: 'rgba(0, 89, 156, 0.4)' },
  { name: 'Git', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/git/git-original.svg', shadow: 'rgba(240, 80, 50, 0.4)' },
  { name: 'GitHub', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/github/github-original.svg', shadow: 'rgba(255, 255, 255, 0.4)' },
  { name: 'Windows', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/windows8/windows8-original.svg', shadow: 'rgba(0, 120, 215, 0.4)' },
  { name: 'Linux', logo: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/linux/linux-original.svg', shadow: 'rgba(252, 198, 36, 0.4)' },
];

const Skills = () => {
  return (
    <section id="skills" className="crazy-skills-section">
      {/* Immersive Animated Background */}
      <div className="skills-mesh-bg"></div>

      <div className="container relative z-10">
        <motion.div
          className="skills-crazy-header"
          initial={{ opacity: 0, y: -50 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8, type: "spring" }}
        >
          <div className="neon-badge-wrapper">
            <span className="skills-neon-badge">⚡ Tech Ecosystem</span>
          </div>
          <h2 className="skills-epic-title">
            Skills & <span className="text-gradient">Technologies</span>
          </h2>
          <p className="skills-epic-subtitle">The tools, languages, and frameworks in my arsenal</p>
        </motion.div>

        <motion.div
          className="crazy-skills-grid"
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          variants={{
            visible: { transition: { staggerChildren: 0.1 } },
            hidden: {}
          }}
        >
          {skillsData.map((skill, index) => (
            <motion.div
              key={index}
              className="skill-cube-wrapper"
              variants={{
                hidden: { opacity: 0, scale: 0.5, y: 50 },
                visible: { opacity: 1, scale: 1, y: 0, transition: { type: "spring", bounce: 0.5, duration: 0.8 } }
              }}
              whileHover={{
                scale: 1.15,
                rotateZ: Math.random() > 0.5 ? 5 : -5,
                transition: { type: "spring", stiffness: 300, damping: 15 }
              }}
              style={{ '--shadow-color': skill.shadow }}
            >
              <div className="skill-cube">
                <div className="skill-glow-bg"></div>
                <div className="skill-logo-container">
                  <img src={skill.logo} alt={skill.name} className="skill-original-logo" />
                </div>
                <h3 className="skill-name">{skill.name}</h3>
                <div className="hover-sparkle"></div>
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
};

export default Skills;
